  await app.click('New','document.querySelector("section[aria-label=Panels]")');await app.until(`!!document.querySelector('[aria-label="Panel name"]')`,'Panel builder did not create draft');
  await app.change('[aria-label="Panel name"]',name);await app.click('Toggle','document.querySelector(".compiled-designer .workspace>aside:first-child")');
