  await app.until(`Array.from(document.querySelectorAll('[aria-label="Panel configuration"] input[type="checkbox"]')).some(input=>input.value===${JSON.stringify(companionId)})`,'New browser was not listed in assignment form');
  await app.evaluate(`(()=>{const input=[...document.querySelectorAll('[aria-label="Panel configuration"] input[type="checkbox"]')].find(input=>input.value===${JSON.stringify(companionId)});input.checked=true;input.dispatchEvent(new Event('change',{bubbles:true}));})()`);
  await app.click('Compile',scope);await app.until(`!!document.querySelector('[aria-label="Compiled resources"]')`,'Actual panel compilation failed',600);checks.push('Normal panel UI adds Toggle, edits exact pixel placement and compiles the current layout.');
  await app.click('Try',scope);await app.until(`!!document.querySelector('.stage .compiled-widget[data-frame-id]:not([data-frame-id=""])')`,'Compiled panel Try did not render');
  await app.pointer('.stage .compiled-hit');await app.until(`Object.values(JSON.parse(document.querySelector('[aria-label="Requested outputs"]').textContent)).includes(true)`,'Panel Try did not emit requested toggle');await app.click('Stop',scope);
  await app.click('Save',scope);await app.until(`(()=>{const error=document.querySelector('[aria-label="Notifications"] .toast.error p');if(error)throw Error(error.textContent);return document.querySelector('.compiled-designer>.section-heading p').textContent.startsWith('Saved');})()`,'Actual panel Save/assignment failed',600);
  await page.bringToFront();await page.getByText('Connected · panel active',{exact:true}).waitFor({timeout:30000});await page.waitForFunction(()=>!!document.querySelector('.compiled-widget[data-frame-id]:not([data-frame-id=""])'));
