  const assigned=await current();assert.ok(assigned.armed);instanceId=assigned.instanceId;await writeFile(join(directory,'ownership.json'),JSON.stringify({companionId,instanceId,createdByThisRun:true},null,2));await page.locator('.compiled-hit').click();for(let i=0;i<100;i++){if(Object.values((await current()).values??{}).includes(true))break;await pause(50);}assert.ok(Object.values((await current()).values??{}).includes(true),'Assigned browser did not submit true to its native instance.');await page.locator('.compiled-hit').click();
  checks.push('Normal Save publishes and assigns the compiled layout; real browser controls reach that native companion instance.');
