 const modal='document.querySelector(".generic-designer")',left='document.querySelector(".generic-designer .form-grid>section:first-child")',right='document.querySelector(".generic-designer .form-grid>section:last-child")',properties=`document.querySelector('.generic-designer [aria-label="Layer properties"]')`;
