  await app.click('Bind x',modal);await fieldIn(app,properties,'[aria-label="x operator"]','if');await fieldIn(app,properties,'[aria-label="Condition operator"]','ref');await fieldIn(app,properties,'[aria-label="Condition reference"]','requested');await fieldIn(app,properties,'[aria-label="Then value"]',230);await fieldIn(app,properties,'[aria-label="Else value"]',30);
  await addPrimitive(app,'text');await app.change('[aria-label="Layer x"]',160);await app.change('[aria-label="Layer y"]',148);await app.change('[aria-label="Layer fontSize"]',14);await labeled(app,properties,'Align','center');
  await app.evaluate(`[...(${properties}).querySelectorAll('summary')].find(summary=>summary.textContent==='Text expression').click()`);await fieldIn(app,properties,'[aria-label="Text operator"]','if');await fieldIn(app,properties,'[aria-label="Condition operator"]','ref');await fieldIn(app,properties,'[aria-label="Condition reference"]','confirmed');for(const [branch,text]of[['Then','Confirmed ON'],['Else','Confirmed OFF']]){await fieldIn(app,properties,`[aria-label="${branch} value type"]`,'string');await fieldIn(app,properties,`[aria-label="${branch} value"]`,text);}
  checks.push('Normal primitive, geometry and expression forms create the capsule track, data-bound thumb and independently bound confirmation label.');
  await app.click('Compile',modal);await app.until(`document.querySelector('.generic-designer .buildbar [role="status"]').textContent==='Compilation complete'`,'Blank capsule compile failed',600);await app.click('Try',modal);await app.until(`!!document.querySelector('.try-canvas .compiled-hit')`,'Blank capsule did not render');const initialFrame=await app.evaluate(`document.querySelector('.try-canvas .compiled-widget').dataset.frameId`);
