test('actual published browser gauges receive synthetic session-bound telemetry through the normal wire handler',{timeout:300000},async()=>{
 const app=await nativeCockpit(),require=createRequire(import.meta.url),{chromium}=require(process.env.OSG_PLAYWRIGHT_MODULE??'C:/Users/ivang/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
 const directory=resolve('.research/generic-widget-telemetry-native',String(Date.now()));await mkdir(directory,{recursive:true});const checks=[],traces=[],owned=[];let browser,page,companionId,activeTrace;const errors=[];
 try{
  const host=await app.request('companion_status');assert.ok(host.listener?.enabled);const before=new Set(host.host.clients.map(client=>client.companionId));
  browser=await chromium.launch({headless:true,channel:process.env.OSG_BROWSER_CHANNEL??'msedge'});const context=await browser.newContext({viewport:{width:1000,height:800}});page=await context.newPage();page.on('pageerror',error=>errors.push(error.message));
  // Only this test replaces received visual samples. Authentication, publication,
  // identity, baseline, heartbeat and host authority still use the real service.
  // Synthetic game-confirmed labels here qualify the browser decoder/reducer;
  // native provenance admission is tested separately, never bypassed in product.
  await page.addInitScript(()=>{
   const Native=window.WebSocket,descriptor=Object.getOwnPropertyDescriptor(Native.prototype,'onmessage');window.__gaugeFixture={channel:undefined,status:'unknown',value:0,revision:1,streaming:true,trace:[]};
   window.WebSocket=new Proxy(Native,{construct(target,args){const socket=Reflect.construct(target,args);let handler,first=true;Object.defineProperty(socket,'onmessage',{configurable:true,get:()=>handler,set(value){handler=value;descriptor.set.call(socket,value?event=>{let received=event;try{const reply=JSON.parse(event.data),stimulus=window.__gaugeFixture;if(reply.feedback&&stimulus.channel){const original=reply.feedback,mode=first||reply.type==='feedback-resync'?'snapshot':'delta';first=false;if(stimulus.streaming)stimulus.revision++;reply.feedback={...original,bindingGeneration:'1',sequence:String(stimulus.revision),mode,values:[{channelId:stimulus.channel.channelId,outputId:stimulus.channel.id,status:stimulus.status,...(stimulus.status==='fresh'||stimulus.status==='stale'?{value:stimulus.value}:{}),provenance:'game-confirmed',sourceKind:'simulator',sourceAgeMs:0,unit:'rpm',range:{min:0,max:8000}}]};if(mode==='snapshot')reply.feedback.bindings=[{channelId:stimulus.channel.channelId,outputId:stimulus.channel.id}];else delete reply.feedback.bindings;stimulus.trace.push({type:reply.type,mode,sequence:reply.feedback.sequence,status:stimulus.status,value:stimulus.value,originalGraphics:/"base64"\s*:/.test(event.data)});received=new MessageEvent('message',{data:JSON.stringify(reply.feedback?reply:original),origin:event.origin});}}catch{}handler.call(socket,received);}:null);}});return socket;}});
  });
  const cdp=await context.newCDPSession(page),audioNodes=[];await cdp.send('WebAudio.enable');cdp.on('WebAudio.audioNodeCreated',event=>audioNodes.push(event.node.nodeType));
  const offer=await app.request('companion_pair_offer',{kind:'browser'});await page.goto(offer.pairing.browserUrl,{waitUntil:'domcontentloaded'});for(let i=0;i<200;i++){companionId=(await app.request('companion_status')).host.clients.find(client=>!before.has(client.companionId))?.companionId;if(companionId)break;await pause(100);}assert.ok(companionId);await writeFile(join(directory,'ownership.json'),JSON.stringify({companionId,instances:owned,createdByThisRun:true},null,2));
  for(const [kind,source]of[['linear',createLinearGaugeFixture()],['radial',createRadialGaugeFixture()]]){
   source.assets=[createPcmSoundFixture()];source.sounds=[{id:'redline',cue:'redline',assetId:'click-wave',volume:.1,cooldownMs:20,stopOnExit:true}];
   const bundle=await compileWidget(source),publication=await createCompiledPanel({id:'telemetry-'+randomUUID().slice(0,8),title:kind+' telemetry qualification',viewports:[{pageId:'main',title:'Main',width:640,height:480}]},[{id:'gauge',label:source.title,pageId:'main',bounds:{x:0,y:0,width:source.size.width/640,height:source.size.height/480},bundle}]);
   await sendPublication(publication,(command,payload)=>app.request(command,payload),{saveAsLatest:false});const instanceId='telemetry-'+randomUUID();owned.push(instanceId);await writeFile(join(directory,'ownership.json'),JSON.stringify({companionId,instances:owned,createdByThisRun:true},null,2));
   await page.evaluate(channel=>{window.__gaugeFixture.channel=channel;window.__gaugeFixture.status='unknown';window.__gaugeFixture.value=0;window.__gaugeFixture.revision=1;window.__gaugeFixture.streaming=true;window.__gaugeFixture.trace=[];},publication.document.ui.feedbackWidgets[0]);
   await app.request('companion_assign',{companionId,instanceId,publicationHash:publication.publicationHash});await page.getByText('Connected · panel active',{exact:true}).waitFor({timeout:30000});await page.waitForFunction(hash=>document.querySelector('.compiled-panel')?.dataset.publicationHash===hash,publication.publicationHash);await page.waitForFunction(()=>!!document.querySelector('.compiled-widget[data-frame-id]:not([data-frame-id=""])'));
   await page.getByRole('button',{name:'♪ Enable sound',exact:true}).click();await page.getByText('Audio: available',{exact:true}).waitFor();
   const domain=bundle.artifact.domains.find(domain=>domain.signal==='rpm'),observations=[];activeTrace={kind,artifactHash:bundle.artifactHash,samples:domain.values.length,maxErrorPixels:domain.maxErrorPixels,observations};
   const compare=async(raw,quality,alarm)=>{const sample=domain.values.reduce((nearest,value)=>Math.abs(value-raw)<Math.abs(nearest-raw)?value:nearest,domain.values[0]),frame=bundle.artifact.frames.find(frame=>frame.selector?.values.rpm===sample&&frame.selector.values.quality===quality&&frame.selector.regions.alarm===alarm);assert.ok(frame);try{await page.waitForFunction(frame=>document.querySelector('.compiled-widget')?.dataset.frameId===frame,frame.id,{timeout:4000});}catch(error){const current=await page.evaluate(()=>({frame:document.querySelector('.compiled-widget')?.dataset.frameId,stimulus:window.__gaugeFixture,body:document.body.innerText}));activeTrace.failure={expected:{raw,quality,alarm,sample,frame:frame.id,selector:frame.selector},actualSelector:bundle.artifact.frames.find(frame=>frame.id===current.frame)?.selector,current};throw error;}const actual=await page.locator('.compiled-widget canvas').evaluate(canvas=>Array.from(canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data)),expected=decodeCompiledFrame(bundle.artifact,bundle.assets,frame.id);let differing=0;for(let i=0;i<expected.length;i++){if(i%4===3)assert.equal(actual[i],expected[i]);else if(expected[i-i%4+3]>32&&Math.abs(actual[i]-expected[i])>4)differing++;}assert.equal(differing,0);observations.push({raw,quality,alarm,sample,frame:frame.id});};
   const stimulus=async(value,status='fresh')=>{const revision=await page.evaluate(({value,status})=>{const fixture=window.__gaugeFixture;fixture.value=value;fixture.status=status;return ++fixture.revision;},{value,status});await page.waitForFunction(revision=>window.__gaugeFixture.trace.some(frame=>Number(frame.sequence)>=revision),revision,{timeout:3000});};
   await compare(0,'unknown','normal');for(const rpm of[0,1000,2000,3000,4000,5000,6000,7000,8000,7000,6000,5000,4000,3000,2000,1000,0]){await stimulus(rpm);await compare(rpm,'fresh',rpm>=7000?'redline':'normal');}
   const cuesBefore=audioNodes.filter(type=>/buffer/i.test(type)).length;for(const [rpm,alarm]of[[6999,'normal'],[7000,'redline'],[6950,'redline'],[6801,'redline'],[6800,'normal']]){await stimulus(rpm);await compare(rpm,'fresh',alarm);}assert.ok(audioNodes.filter(type=>/buffer/i.test(type)).length>cuesBefore,'A fresh telemetry edge did not play its optional compiled cue.');
   await stimulus(7500);await compare(7500,'fresh','redline');await page.evaluate(()=>window.__gaugeFixture.streaming=false);await pause(600);await compare(0,'stale','normal');for(const quality of['disconnected','unknown']){await stimulus(4000,quality);await compare(0,quality,'normal');}await page.evaluate(()=>window.__gaugeFixture.streaming=true);await stimulus(4000);await compare(4000,'fresh','normal');
   const cuesBeforeSnapshot=audioNodes.filter(type=>/buffer/i.test(type)).length;await page.getByRole('button',{name:'↻ Clear visual state',exact:true}).click();await stimulus(7500);await page.getByRole('button',{name:'↻ Resync visuals',exact:true}).click();await compare(7500,'fresh','redline');assert.equal(audioNodes.filter(type=>/buffer/i.test(type)).length,cuesBeforeSnapshot,'An explicit restored snapshot replayed a cue.');
   const trace=await page.evaluate(()=>window.__gaugeFixture.trace);assert.ok(trace.some(frame=>frame.mode==='snapshot'));assert.ok(trace.some(frame=>frame.mode==='delta'));assert.equal(trace.some(frame=>frame.originalGraphics),false);assert.ok(domain.maxErrorPixels<=(kind==='linear'?1:2));
   await page.screenshot({path:join(directory,kind+'-telemetry.png'),fullPage:true});activeTrace.wireStimulus=trace;traces.push(activeTrace);activeTrace=undefined;checks.push(kind+' published browser feedback covers min/mid/max, a full-range sweep, raw redline hysteresis, stale/unknown/disconnected recovery, live cue edges and silent snapshot restoration.');await app.request('companion_unassign',{instanceId});
  }
  assert.deepEqual(errors,[]);await writeFile(join(directory,'evidence.json'),JSON.stringify({actualNativeCockpit:true,actualProductionBrowser:true,stimuli:'Synthetic session-bound feedback receive interception through the unchanged production wire validator, CompiledPanel and player. No real simulator or native provenance qualification is claimed.',checks,traces},null,2));console.log(JSON.stringify({directory,checks}));
 }catch(error){await writeFile(join(directory,'failure.json'),JSON.stringify({error:String(error),companionId,instances:owned,checks,errors,traces,activeTrace,body:await page?.evaluate(()=>document.body.innerText).catch(()=>null)},null,2));throw error;}
 finally{await browser?.close();await app.send('Page.bringToFront').catch(()=>{});for(const instanceId of owned)await app.request('companion_unassign',{instanceId}).catch(()=>{});if(companionId)await app.request('companion_revoke',{companionId}).catch(()=>{});await app.close();}
});
